// Mirrors the FastAPI response models (backend/app/schemas, backend/app/ml/types.py).
// src/test/contract.test.ts type-checks JSON generated by the real backend against these.

export type ExperienceLevel = 'beginner' | 'intermediate' | 'advanced'

export interface ProfileInput {
  skills: string[]
  learning_interests: string[]
  experience_level: ExperienceLevel
  domains: string[]
  preferred_languages: string[]
}

export interface SavedProfile extends ProfileInput {
  id: number
  created_at: string
}

export interface Issue {
  id: number
  number: number
  title: string
  body: string
  url: string
  state: string
  labels: string[]
  comments: number
  created_at: string
  updated_at: string
  repo_full_name: string
  repo_url: string
  repo_description: string | null
  repo_language: string | null
  repo_stars: number | null
  repo_pushed_at: string | null
}

export interface ScoreBreakdown {
  overall: number
  semantic_similarity: number
  skill_compatibility: number
  experience_compatibility: number
  repository_activity: number
  beginner_friendliness: number
}

export interface Recommendation {
  rank: number
  issue: Issue
  scores: ScoreBreakdown
  cosine_similarity: number
  matching_skills: string[]
  relevant_labels: string[]
  explanation: string
  potential_skills_to_learn: string[]
  difficulty_signals: string[]
}

export interface RecommendationRun {
  id: number
  profile_id: number
  created_at: string
  issues_analyzed: number
  top_k: number
  model: string
  weights: Record<string, number>
  search_queries: string[]
  warnings: string[]
  stale_data: boolean
  recommendations: Recommendation[]
}

export interface HistoryEntry {
  id: number
  profile_id: number
  created_at: string
  experience_level: string
  skills: string[]
  domains: string[]
  issues_analyzed: number
  recommendation_count: number
  top_score: number | null
}

export interface HistoryResponse {
  total: number
  limit: number
  offset: number
  items: HistoryEntry[]
}

export interface CountItem {
  label: string
  count: number
}

export interface AnalyticsResponse {
  totals: {
    profiles: number
    recommendation_runs: number
    recommendations_generated: number
    issues_analyzed: number
    unique_issues_recommended: number
    cached_issues: number
  }
  average_scores: ScoreBreakdown | null
  score_distribution: CountItem[]
  skill_compatibility_distribution: CountItem[]
  matching_skill_count_distribution: CountItem[]
  top_matching_skills: CountItem[]
  requested_domains: CountItem[]
  recommended_language_distribution: CountItem[]
  top_labels: CountItem[]
  experience_level_distribution: CountItem[]
}

export interface HealthResponse {
  status: 'ok' | 'degraded'
  app: string
  version: string
  environment: string
  database: 'ok' | 'unavailable'
}

/** Error body returned by every failing backend request. */
export interface ApiErrorBody {
  error: { code: string; message: string; details?: unknown }
}
